package com.portfolio.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="POSHIST")
public class PositionHistory {
 @EmbeddedId private PositionHistoryId id; @Column(name="TRANS_TYPE",columnDefinition="char(2)") private String transType; @Column(name="SECURITY_ID",columnDefinition="char(12)") private String securityId; @Column(precision=15,scale=3) private BigDecimal quantity; @Column(precision=15,scale=3) private BigDecimal price; @Column(precision=15,scale=2) private BigDecimal amount; @Column(precision=15,scale=2) private BigDecimal fees; @Column(name="TOTAL_AMOUNT",precision=15,scale=2) private BigDecimal totalAmount; @Column(name="COST_BASIS",precision=15,scale=2) private BigDecimal costBasis; @Column(name="GAIN_LOSS",precision=15,scale=2) private BigDecimal gainLoss; private LocalDate processDate; private LocalTime processTime; @Column(name="PROGRAM_ID",columnDefinition="char(8)") private String programId; @Column(name="USER_ID",columnDefinition="char(8)") private String userId; private LocalDateTime auditTimestamp;
 public PositionHistory(){} public PositionHistoryId getId(){return id;} public void setId(PositionHistoryId v){id=v;} public String getTransType(){return transType;} public void setTransType(String v){transType=v;} public String getSecurityId(){return securityId;} public void setSecurityId(String v){securityId=v;} public BigDecimal getQuantity(){return quantity;} public void setQuantity(BigDecimal v){quantity=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public BigDecimal getFees(){return fees;} public void setFees(BigDecimal v){fees=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public BigDecimal getCostBasis(){return costBasis;} public void setCostBasis(BigDecimal v){costBasis=v;} public BigDecimal getGainLoss(){return gainLoss;} public void setGainLoss(BigDecimal v){gainLoss=v;} public LocalDate getProcessDate(){return processDate;} public void setProcessDate(LocalDate v){processDate=v;} public LocalTime getProcessTime(){return processTime;} public void setProcessTime(LocalTime v){processTime=v;} public String getProgramId(){return programId;} public void setProgramId(String v){programId=v;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public LocalDateTime getAuditTimestamp(){return auditTimestamp;} public void setAuditTimestamp(LocalDateTime v){auditTimestamp=v;}
}
